#!/usr/bin/env python3 -I
"""Generates custom-sql/017_pet_standin_scale.sql: the pet-sized DisplayScale of every stand-in template (entry 9000000 + species), so a pet is BORN at its pet size (no full-size
flash before the client gets the SetScale update). Input pet-battle/.s/scales_rows.tsv (species, Idx, scale) is dumped from the live server (PB_STORE.Scale for every stand-in species).
Usage (project root): python3 -I pet-battle/gen_standin_scale_sql.py"""
rows = [l.split("\t") for l in open("pet-battle/.s/scales_rows.tsv").read().split("\n") if l.strip()]   # entry, model row Idx, scale (dumped from the live server: PB_STORE.ScaleOf(entry, display) per template model row)
out = ["-- GENERATED by pet-battle/gen_standin_scale_sql.py - do not edit. Pet-sized DisplayScale for every pet stand-in template (%d species). Idempotent." % len(rows), "USE acore_world;"]
for i in range(0, len(rows), 200):
    chunk = rows[i:i + 200]
    case = " ".join("WHEN '%d-%s' THEN %s" % (9000000 + int(e), ix, sc) for e, ix, sc in chunk)
    ids = ",".join("'%d-%s'" % (9000000 + int(e), ix) for e, ix, _ in chunk)
    out.append("UPDATE creature_template_model SET DisplayScale = CASE CONCAT(CreatureID, '-', Idx) %s END WHERE CONCAT(CreatureID, '-', Idx) IN (%s);" % (case, ids))
open("custom-sql/017_pet_standin_scale.sql", "w").write("\n".join(out) + "\n")
print("custom-sql/017_pet_standin_scale.sql written (%d species)" % len(rows))
